from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

# Initialize the Azure Form Recognizer client with your endpoint and key
endpoint = "https://<your-form-recognizer-endpoint>.cognitiveservices.azure.com/"
key = "<your-azure-form-recognizer-key>"
credential = AzureKeyCredential(key)
document_analysis_client = DocumentAnalysisClient(
    endpoint=endpoint, credential=credential
)

def extract_receipt_data(receipt_image_path):
    """
    Extracts merchant, tax, total, and items from a receipt image using Azure Form Recognizer.

    Args:
        receipt_image_path (str): Path to the receipt image file.

    Returns:
        dict: Structured data containing merchant, tax, total, and items extracted from the receipt.
    """
    with open(receipt_image_path, "rb") as f:
        poller = document_analysis_client.begin_analyze_document("prebuilt-invoice", f)
    result = poller.result()

    extracted_data = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": []
    }

    for doc in result.documents:
        # Extract merchant name
        for field in doc.fields:
            if field.name.lower() == "vendor":
                if field.value_type == "string":
                    extracted_data["merchant"] = field.value.as_string()

        # Extract tax and total amounts
        for field in doc.fields:
            field_name = field.name.lower()
            if field_name == "tax":
                if field.value_type == "number":
                    extracted_data["tax"] = field.value.as_float()
            elif field_name == "total":
                if field.value_type == "number":
                    extracted_data["total"] = field.value.as_float()

        # Extract line items
        for field in doc.fields:
            if field.name.lower() == "items":
                if field.value_type == "list":
                    for item in field.value:
                        item_data = {}
                        for sub_field in item:
                            if sub_field.value_type == "string":
                                item_data[sub_field.name.lower()] = sub_field.value.as_string()
                            elif sub_field.value_type == "number":
                                item_data[sub_field.name.lower()] = sub_field.value.as_float()
                        extracted_data["items"].append(item_data)

    return extracted_data
